import { readdir, unlink } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

/**
 * Names generated by Pi's native clipboard-image paste handler.
 *
 * Keep this deliberately strict: the cleanup command must never remove an
 * unrelated file from the system temporary directory.
 */
export const PI_CLIPBOARD_IMAGE_PATTERN =
	/^pi-clipboard-[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}\.(?:png|jpe?g|webp|gif)$/i;

export type CleanupFailure = {
	name: string;
	error: string;
};

export type ClipboardCleanupResult = {
	directory: string;
	matched: number;
	deleted: string[];
	failed: CleanupFailure[];
};

/** Return true when a filename is a Pi-generated clipboard image. */
export function isPiClipboardImageFile(name: string): boolean {
	return PI_CLIPBOARD_IMAGE_PATTERN.test(name);
}

function errorCode(error: unknown): string | undefined {
	if (typeof error !== "object" || error === null || !("code" in error)) return undefined;
	const code = (error as { code?: unknown }).code;
	return typeof code === "string" ? code : undefined;
}

/**
 * Delete Pi clipboard images from the system temporary directory.
 *
 * The directory is injectable so the matching and deletion behavior can be
 * tested without touching the real temporary directory.
 */
export async function cleanupClipboardImages(directory = tmpdir()): Promise<ClipboardCleanupResult> {
	const entries = await readdir(directory, { withFileTypes: true });
	const candidates = entries.filter(
		(entry) => entry.isFile() && isPiClipboardImageFile(entry.name),
	);
	const deleted: string[] = [];
	const failed: CleanupFailure[] = [];

	for (const entry of candidates) {
		try {
			await unlink(join(directory, entry.name));
			deleted.push(entry.name);
		} catch (error) {
			// A concurrent cleanup may have removed the file already.
			if (errorCode(error) === "ENOENT") continue;
			failed.push({
				name: entry.name,
				error: error instanceof Error ? error.message : String(error),
			});
		}
	}

	return {
		directory,
		matched: candidates.length,
		deleted,
		failed,
	};
}
